 DemoState state=new(); string role="Quản lý", user="Người dùng Demo", active="home"; int? selectedTable; DateTime otpUntil; bool otpVerified; DispatcherTimer? otpTimer;
 static readonly (string Key,string Label,string Description)[] Pages={ ("home","Tổng quan","Tình hình nhà hàng theo vai trò hiện tại."),("tables","Quản lý bàn","Quản lý trạng thái bàn."),("payment","Thanh toán","Kiểm tra hóa đơn, nhận tiền và chuyển bàn sang Chờ Dọn."),("invoices","Hóa đơn","Danh sách hóa đơn và xem trước phiếu in."),("menu","Thực đơn","Danh mục món ăn, giá bán và tình trạng phục vụ."),("inventory","Quản lý kho","Tồn nguyên liệu và cảnh báo tồn tối thiểu."),("staff","Nhân viên","Nhân viên và tài khoản."),("shifts","Ca làm việc","Lịch phân công nhân viên."),("promos","Khuyến mãi","Chương trình ưu đãi."),("reports","Thống kê","Doanh thu đã thanh toán."),("chat","Chat nội bộ","Trao đổi trong phiên demo."),("logs","Nhật ký","Lịch sử thao tác."),("profile","Hồ sơ","Thông tin tài khoản và đổi mật khẩu.")};
 bool Allowed(string k)=>role=="Quản lý" || (role=="Thu ngân" ? new[]{"home","tables","payment","invoices","chat","profile"}.Contains(k):new[]{"home","tables","chat","profile"}.Contains(k));
 bool CanOrder=>role is "Quản lý" or "Phục vụ"; bool CanPay=>role is "Quản lý" or "Thu ngân"; bool IsManager=>role=="Quản lý";
 public MainWindow(){InitializeComponent();Logout.Click+=(_,_)=>ShowLogin();ResetDemo.Click+=(_,_)=>{if(Ask("Đặt lại toàn bộ dữ liệu demo?")){state=new();selectedTable=null;Navigate("home");}};ShowWelcome();}
 static T At<T>(FrameworkElement v,string name) where T:FrameworkElement => (T)(v.FindName(name)??throw new InvalidOperationException("Không tìm thấy control "+name));
 static void Click(FrameworkElement v,string n,Action a)=>At<Button>(v,n).Click+=(_,_)=>a();
 static string Text(FrameworkElement v,string n)=>At<TextBox>(v,n).Text.Trim(); static string Secret(FrameworkElement v,string n)=>At<PasswordBox>(v,n).Password;
 static string Choice(FrameworkElement v,string n)=>(At<ComboBox>(v,n).SelectedItem as ComboBoxItem)?.Content?.ToString()??"";
 static void SetChoice(FrameworkElement v,string n,string val){var c=At<ComboBox>(v,n);for(int i=0;i<c.Items.Count;i++)if((c.Items[i] as ComboBoxItem)?.Content?.ToString()==val){c.SelectedIndex=i;return;}}
 static void Set(FrameworkElement v,string n,string val)=>At<TextBox>(v,n).Text=val;
 static void Label(FrameworkElement v,string n,object? val)=>At<TextBlock>(v,n).Text=val?.ToString()??"";
 static DataGrid GridAt(FrameworkElement v,string n="Rows")=>At<DataGrid>(v,n);
