 static string Money(decimal x)=>Currency.Money(x); decimal Revenue=>state.Bills.Where(x=>x.Paid).Sum(x=>x.Due);
 void Msg(string s)=>MessageBox.Show(this,s,"Quản Lý Nhà Hàng",MessageBoxButton.OK,MessageBoxImage.Information);
