 void Auth(UserControl v){otpTimer?.Stop();Shell.Visibility=Visibility.Collapsed;AuthHost.Visibility=Visibility.Visible;AuthHost.Content=v;}
 void ShowWelcome(){var v=new WelcomeView();Auth(v);Click(v,"Continue",ShowLogin);}
 void ShowLogin(){var v=new LoginView();otpVerified=false;Auth(v);Click(v,"LoginButton",()=>{if(Text(v,"UsernameInput").Length==0||Secret(v,"PasswordInput").Length==0){Msg("Nhập tên đăng nhập và mật khẩu demo.");return;}user=Text(v,"UsernameInput");role=Choice(v,"RoleInput");selectedTable=null;Log("Đăng nhập demo với vai trò "+role);AuthHost.Content=null;AuthHost.Visibility=Visibility.Collapsed;Shell.Visibility=Visibility.Visible;Navigate("home");});Click(v,"ForgotPasswordButton",ShowForgot);Click(v,"SignupButton",ShowSignup);}
 void ShowSignup(){var v=new SignupView();Auth(v);Click(v,"Back",ShowLogin);Click(v,"Submit",()=>{if(new[]{"NameInput","CodeInput","Username"}.Any(n=>Text(v,n)=="")){Msg("Nhập đầy đủ thông tin.");return;}state.Requests.Add(new {Name=Text(v,"NameInput"),Code=Text(v,"CodeInput"),Username=Text(v,"Username")});Msg("Đã ghi nhận yêu cầu đăng ký demo, chưa cấp tài khoản thật.");ShowLogin();});}
 void ShowForgot(){var v=new ForgotView();Auth(v);Click(v,"Back",ShowLogin);Click(v,"Submit",()=>{if(Text(v,"Email")==""){Msg("Nhập tài khoản hoặc email.");return;}otpUntil=DateTime.Now.AddMinutes(2);ShowOtp();});}
 void ShowOtp(){var v=new OtpView();otpVerified=false;Auth(v);var digits=Enumerable.Range(0,6).Select(i=>At<TextBox>(v,$"Digit{i}")).ToArray();bool editing=false;
 void Fill(int start,string raw){var chars=raw.Where(char.IsAsciiDigit).ToArray();editing=true;if(chars.Length==6){start=0;foreach(var d in digits)d.Text="";}int n=Math.Min(chars.Length,6-start);for(int j=0;j<n;j++)digits[start+j].Text=chars[j].ToString();editing=false;digits[Math.Min(start+n,5)].Focus();digits[Math.Min(start+n,5)].SelectAll();}
 for(int i=0;i<6;i++){int j=i;var d=digits[i];d.TextChanged+=(_,_)=>{if(editing)return;string raw=d.Text;if(raw.Length==0)return;var num=raw.Where(char.IsAsciiDigit).ToArray();if(num.Length==0){editing=true;d.Text="";editing=false;return;}Fill(j,new string(num));};d.PreviewKeyDown+=(_,e)=>{if(e.Key==Key.Back&&d.Text==""&&j>0){digits[j-1].Text="";digits[j-1].Focus();e.Handled=true;}};DataObject.AddPastingHandler(d,(_,e)=>{if(e.DataObject.GetDataPresent(DataFormats.UnicodeText)){string raw=(string?)e.DataObject.GetData(DataFormats.UnicodeText)??"";Fill(j,raw);e.CancelCommand();}});}
 void Tick()=>Label(v,"Countdown",$"Mã hết hạn sau {Math.Max(0,(int)Math.Ceiling((otpUntil-DateTime.Now).TotalSeconds))} giây");otpTimer=new DispatcherTimer{Interval=TimeSpan.FromSeconds(1)};otpTimer.Tick+=(_,_)=>Tick();otpTimer.Start();Tick();v.Loaded+=(_,_)=>digits[0].Focus();Click(v,"Resend",()=>{otpUntil=DateTime.Now.AddMinutes(2);ShowOtp();});Click(v,"Back",ShowForgot);Click(v,"Submit",()=>{if(DateTime.Now>otpUntil){Msg("OTP đã hết hạn.");return;}if(string.Concat(digits.Select(d=>d.Text))!="123456"){Msg("Mã thử nghiệm không hợp lệ (dùng 123456).");return;}otpVerified=true;ShowReset();});}
 void ShowReset(){if(!otpVerified){ShowForgot();return;}var v=new ResetView();Auth(v);Click(v,"Back",ShowLogin);Click(v,"Submit",()=>{if(Secret(v,"Password").Length<8||Secret(v,"Password")!=Secret(v,"Confirm")){Msg("Mật khẩu phải có ít nhất 8 ký tự và trùng xác nhận.");return;}Msg("Đã mô phỏng đặt lại mật khẩu. Không thay đổi tài khoản thật.");ShowLogin();});}
 void Navigate(string k){if(!Allowed(k))k="home";active=k;var page=Pages.First(x=>x.Key==k);PageTitle.Text=page.Label;PageSubtitle.Text=page.Description;UserLabel.Text=user+" · "+role;Navigation.Children.Clear();foreach(var x in Pages.Where(x=>Allowed(x.Key))){var b=new Button{Content=x.Label,Style=(Style)FindResource("Nav"),Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(x.Key==k?"#345373":"#203956"))};string key=x.Key;b.Click+=(_,_)=>Navigate(key);Navigation.Children.Add(b);}ViewHost.Content=k switch {"home"=>Home(),"tables"=>Tables(),"payment"=>Payments(),"invoices"=>Invoices(),"menu"=>MenuPage(),"inventory"=>Inventory(),"staff"=>StaffPage(),"shifts"=>Shifts(),"promos"=>Promos(),"reports"=>Reports(),"chat"=>Chat(),"logs"=>Logs(),"profile"=>Profile(),_=>Home()};}
 int Count(string s)=>state.Tables.Count(x=>x.Status==s);
 UserControl Home(){var v=new HomeView();Label(v,"Busy",Count("Có Khách"));Label(v,"Free",Count("Trống"));Label(v,"Cleaning",Count("Chờ Dọn"));Label(v,"Revenue",Money(Revenue));Items(v,state.Tables.Where(t=>t.Status=="Có Khách"||t.Status=="Chờ Dọn").ToList(),"Tables");Click(v,"Open",()=>{if(GridAt(v,"Tables").SelectedItem is DiningTable t){Navigate(ShowTable(t)?"payment":"home");}else Msg("Chọn một bàn.");});Click(v,"GoTables",()=>Navigate("tables"));Click(v,"GoPayment",()=>Navigate("payment"));Click(v,"GoChat",()=>Navigate("chat"));Click(v,"GoInvoices",()=>Navigate("invoices"));Enable(v,"GoPayment",CanPay);Enable(v,"GoInvoices",CanPay);return v;}
 UserControl Tables(){var v=new TablesView();Label(v,"All",state.Tables.Count);Label(v,"Free",Count("Trống"));Label(v,"Busy",Count("Có Khách"));Label(v,"Cleaning",Count("Chờ Dọn"));Enable(v,"Add",IsManager);void Draw(){var host=At<WrapPanel>(v,"TableCards");host.Children.Clear();var filter=Choice(v,"Filter");foreach(var t in state.Tables.Where(t=>filter=="Tất cả"||t.Status==filter)){var card=new Border{Style=(Style)FindResource("Card"),Width=285,MinHeight=150,Margin=new Thickness(0,0,14,14)};var panel=new StackPanel();panel.Children.Add(new TextBlock{Text=t.Name,FontSize=20,FontWeight=FontWeights.Bold});string color=t.Status switch{"Trống"=>"#15805A","Có Khách"=>"#F97316","Đã Đặt"=>"#2867BB",_=>"#A17513"};panel.Children.Add(new TextBlock{Text=t.Status,Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(color)),FontWeight=FontWeights.Bold,Margin=new Thickness(0,8,0,4)});panel.Children.Add(new TextBlock{Text=$"{t.Seats} chỗ · B{t.Id:00}"});var b=new Button{Content="Xem / thao tác",Style=(Style)FindResource("Secondary")};b.Click+=(_,_)=>{Navigate(ShowTable(t)?"payment":"tables");};panel.Children.Add(b);card.Child=panel;host.Children.Add(card);}}At<ComboBox>(v,"Filter").SelectionChanged+=(_,_)=>Draw();Draw();Click(v,"Add",()=>{if(!IsManager)return;SimpleForm("Thêm bàn ăn",new[]{("Tên bàn",$"Bàn {state.Tables.Max(t=>t.Id)+1:00}"),("Sức chứa","4")},values=>{if(!int.TryParse(values[1],out int seats)||seats<=0||values[0]==""||state.Tables.Any(t=>t.Name.Equals(values[0],StringComparison.OrdinalIgnoreCase)))return "Tên bàn hoặc sức chứa không hợp lệ.";state.Tables.Add(new(){Id=state.Tables.Max(t=>t.Id)+1,Name=values[0],Seats=seats});Log("Thêm bàn "+values[0]);return null;});Navigate("tables");});return v;}
 T Own<T>(T w) where T:Window {w.Owner=this;w.Width=Math.Min(w.Width,SystemParameters.WorkArea.Width-24);w.Height=Math.Min(w.Height,SystemParameters.WorkArea.Height-32);return w;}
 bool ShowTable(DiningTable t){bool requested=false;var d=Own(new TableDialog());d.Title=t.Name;void Refresh(){Label(d,"Heading",t.Name);Label(d,"Info",$"{t.Status} · {t.Seats} chỗ");Items(d,t.Orders.ToList(),"Orders");Label(d,"Total","Tạm tính: "+Money(t.Total));Enable(d,"Open",CanOrder&&(t.Status=="Trống"||t.Status=="Đã Đặt"));Enable(d,"Reserve",CanOrder&&t.Status=="Trống");Enable(d,"Order",CanOrder&&t.Status=="Có Khách");Enable(d,"Invoice",(CanOrder||CanPay)&&t.Status=="Có Khách"&&t.Total>0);Enable(d,"Clean",CanOrder&&t.Status=="Chờ Dọn");}Refresh();Click(d,"Open",()=>{t.Status="Có Khách";t.Opened=DateTime.Now;Log("Mở phiên "+t.Name);Refresh();});Click(d,"Reserve",()=>{t.Status="Đã Đặt";Log("Đặt bàn "+t.Name);Refresh();});Click(d,"Clean",()=>{t.Status="Trống";t.Opened=null;t.Orders.Clear();Log("Dọn xong "+t.Name);Refresh();});Click(d,"Order",()=>{ShowOrder(t,d);Refresh();});Click(d,"Invoice",()=>{if(t.Total<=0)return;if(state.Pending(t.Id)==null){state.Bills.Add(new(){Id=$"HD{state.Bills.Count+1:000}",TableName=t.Name,TableId=t.Id,Items=t.Orders.ToList()});Log("Yêu cầu thanh toán "+t.Name);}selectedTable=t.Id;requested=true;d.Close();if(!CanPay)Msg("Đã gửi yêu cầu thanh toán cho thu ngân trong dữ liệu demo.");});Click(d,"Back",d.Close);d.ShowDialog();return requested&&CanPay;}
 void ShowOrder(DiningTable t,Window owner){if(t.Status!="Có Khách"||!CanOrder)return;var d=new OrderDialog{Owner=owner,Width=Math.Min(1180,SystemParameters.WorkArea.Width-24),Height=Math.Min(780,SystemParameters.WorkArea.Height-32)};var draft=new List<OrderLine>();void Filter(){var txt=Text(d,"Search");var cat=Choice(d,"Category");Items(d,state.Foods.Where(f=>f.Active&&(cat=="Tất cả"||f.Category==cat)&&f.Name.Contains(txt,StringComparison.OrdinalIgnoreCase)).ToList(),"Foods");}void Refresh(){Items(d,t.Orders.ToList(),"Confirmed");Items(d,draft.ToList(),"Draft");Label(d,"Total",$"Đã xác nhận: {Money(t.Total)}\nĐang chọn thêm: {Money(draft.Sum(x=>x.Total))}");Enable(d,"Commit",draft.Count>0);}Label(d,"Heading","Gọi món · "+t.Name);At<TextBox>(d,"Search").TextChanged+=(_,_)=>Filter();At<ComboBox>(d,"Category").SelectionChanged+=(_,_)=>Filter();Filter();Refresh();Click(d,"Add",()=>{if(GridAt(d,"Foods").SelectedItem is Food f){DemoState.Add(draft,f);Refresh();}});Click(d,"Minus",()=>{if(GridAt(d,"Draft").SelectedItem is OrderLine l){DemoState.Adjust(draft,l,-1);Refresh();}});Click(d,"Plus",()=>{if(GridAt(d,"Draft").SelectedItem is OrderLine l){DemoState.Adjust(draft,l,1);Refresh();}});Click(d,"Clear",()=>{draft.Clear();Refresh();});Click(d,"Commit",()=>{foreach(var line in draft){int idx=t.Orders.FindIndex(x=>x.FoodId==line.FoodId&&x.Price==line.Price);if(idx<0)t.Orders.Add(line);else t.Orders[idx]=t.Orders[idx] with{Quantity=t.Orders[idx].Quantity+line.Quantity};}draft.Clear();if(state.Pending(t.Id) is Bill pending)pending.Items=t.Orders.ToList();Log("Xác nhận thêm món "+t.Name);Refresh();});Click(d,"Back",d.Close);d.Closing+=(_,e)=>{if(draft.Count>0&&MessageBox.Show(d,"Bỏ các món chưa xác nhận?","Xác nhận",MessageBoxButton.YesNo)!=MessageBoxResult.Yes)e.Cancel=true;};d.ShowDialog();}
 UserControl Payments(){var v=new PaymentView();var pending=state.Bills.Where(x=>!x.Paid).ToList();Label(v,"Waiting",pending.Count);Label(v,"Paid",state.Bills.Count(x=>x.Paid));Label(v,"Revenue",Money(Revenue));Label(v,"Cleaning",Count("Chờ Dọn"));Items(v,pending,"Bills");Bill? Bill()=>GridAt(v,"Bills").SelectedItem as Bill;bool loading=false;void Preview(){if(loading)return;var b=Bill();if(b==null){Label(v,"Due","Chưa chọn hóa đơn");Label(v,"Change","");return;}int discount=At<ComboBox>(v,"Discount").SelectedIndex==1?10:0;decimal due=Math.Round(b.Subtotal*(100-discount)/100,0,MidpointRounding.AwayFromZero);decimal.TryParse(Text(v,"Received"),out var paid);Label(v,"Due","Tiền cần thu: "+Money(due));Label(v,"Change","Tiền thừa: "+Money(Math.Max(0,paid-due)));}void Select(){loading=true;var b=Bill();Enable(v,"Pay",b!=null&&CanPay);Enable(v,"Edit",b!=null&&CanPay);Label(v,"Selected",b==null?"Chưa chọn hóa đơn":$"{b.Id} · {b.TableName}\nTổng tiền hàng: {Money(b.Subtotal)}");At<ComboBox>(v,"Discount").SelectedIndex=b?.Discount==10?1:0;SetChoice(v,"Method",b?.Method??"Tiền mặt");Set(v,"Received",b?.Due.ToString("0")??"");loading=false;Preview();}GridAt(v,"Bills").SelectionChanged+=(_,_)=>Select();At<ComboBox>(v,"Discount").SelectionChanged+=(_,_)=>Preview();At<TextBox>(v,"Received").TextChanged+=(_,_)=>Preview();GridAt(v,"Bills").SelectedItem=pending.FirstOrDefault(b=>b.TableId==selectedTable)??pending.FirstOrDefault();Select();Click(v,"Edit",()=>{if(Bill() is Bill b){EditBill(b);Navigate("payment");}});Click(v,"Pay",()=>{var b=Bill();if(b==null||b.Paid||!CanPay)return;int disc=At<ComboBox>(v,"Discount").SelectedIndex==1?10:0;decimal due=Math.Round(b.Subtotal*(100-disc)/100,0,MidpointRounding.AwayFromZero);string method=Choice(v,"Method");if(!decimal.TryParse(Text(v,"Received"),out var received)||received<due||(method=="Chuyển khoản"&&received!=due)){Msg("Số tiền không hợp lệ. Chuyển khoản cần đúng số tiền cần thu.");return;}if(!Ask($"Xác nhận thu {Money(due)} qua {method}?"))return;b.Discount=disc;b.Method=method;b.PaidAt=DateTime.Now;state.Tables.First(t=>t.Id==b.TableId).Status="Chờ Dọn";Log("Thanh toán "+b.Id);Navigate("payment");});return v;}
 UserControl Invoices(){var v=new InvoicesView();Items(v,state.Bills.AsEnumerable().Reverse().ToList());Click(v,"GoTables",()=>Navigate("tables"));Click(v,"Edit",()=>{if(GridAt(v).SelectedItem is Bill b){if(b.Paid){Msg("Hóa đơn đã thanh toán không được sửa trực tiếp.");return;}EditBill(b);Navigate("invoices");}else Msg("Chọn hóa đơn.");});Click(v,"Preview",()=>{if(GridAt(v).SelectedItem is Bill b)PreviewBill(b);else Msg("Chọn hóa đơn.");});return v;}
 void EditBill(Bill b){if(b.Paid||!CanPay)return;var d=Own(new InvoiceEditDialog());d.Title="Chỉnh sửa hóa đơn "+b.Id;var draft=b.Items.ToList();SetChoice(d,"Method",b.Method);var combo=At<ComboBox>(d,"Food");combo.ItemsSource=state.Foods.Where(x=>x.Active).ToList();combo.SelectedIndex=0;void Refresh(){Items(d,draft.ToList());Label(d,"Total","Tổng tiền hàng: "+Money(draft.Sum(x=>x.Total)));}Refresh();Click(d,"Plus",()=>{if(GridAt(d).SelectedItem is OrderLine l){DemoState.Adjust(draft,l,1);Refresh();}});Click(d,"Minus",()=>{if(GridAt(d).SelectedItem is OrderLine l){DemoState.Adjust(draft,l,-1);Refresh();}});Click(d,"Add",()=>{if(combo.SelectedItem is Food f){DemoState.Add(draft,f);Refresh();}});Click(d,"Cancel",d.Close);Click(d,"Save",()=>{if(draft.Count==0){Msg("Hóa đơn cần ít nhất một món.");return;}b.Items=draft.ToList();b.Method=Choice(d,"Method");state.Tables.First(x=>x.Id==b.TableId).Orders=b.Items.ToList();Log("Sửa hóa đơn "+b.Id);d.Close();});d.ShowDialog();}
 void PreviewBill(Bill b){var d=Own(new ReceiptDialog());Label(d,"Body",$"Mã: {b.Id}\nBàn: {b.TableName}\nNgày: {b.Created}\n\n"+string.Join("\n",b.Items.Select(x=>$"{x.Name}\n  {x.Quantity} × {Money(x.Price)} = {x.TotalText}"))+$"\n\nTổng tiền hàng: {b.SubtotalText}\nGiảm giá: {b.Discount}%\nCần thu: {b.DueText}\nPhương thức: {b.Method}\n{b.Status}");Click(d,"CloseButton",d.Close);Click(d,"Print",()=>{var print=new PrintDialog();if(print.ShowDialog()==true)print.PrintVisual(At<Border>(d,"Receipt"),b.Id);});d.ShowDialog();}
 void SimpleForm(string title,(string Label,string Value)[] fields,Func<string[],string?> save){var d=Own(new FormDialog());d.Title=title;Label(d,"Heading",title);var p=At<StackPanel>(d,"Fields");var boxes=new List<TextBox>();foreach(var f in fields){p.Children.Add(new TextBlock{Text=f.Label,FontWeight=FontWeights.SemiBold});var box=new TextBox{Text=f.Value};p.Children.Add(box);boxes.Add(box);}Click(d,"Cancel",d.Close);Click(d,"Save",()=>{var err=save(boxes.Select(x=>x.Text.Trim()).ToArray());if(err!=null){MessageBox.Show(d,err);return;}d.Close();});d.ShowDialog();}
 UserControl MenuPage(){var v=new MenuView();Items(v,state.Foods);Click(v,"Add",()=>{EditFood(null);Navigate("menu");});Click(v,"Edit",()=>{if(GridAt(v).SelectedItem is Food f){EditFood(f);Navigate("menu");}else Msg("Chọn món.");});return v;}
 void EditFood(Food? f){if(!IsManager)return;SimpleForm(f==null?"Thêm món":"Chỉnh sửa món",new[]{("Tên món",f?.Name??""),("Danh mục",f?.Category??"Món chính"),("Đơn vị",f?.Unit??"phần"),("Đơn giá (đ)",f?.Price.ToString("0")??""),("Trạng thái (Đang bán / Ngừng bán)",f?.Status??"Đang bán")},x=>{if(x[0]==""||x[1]==""||x[2]==""||!decimal.TryParse(x[3],out var price)||price<=0||x[4] is not ("Đang bán" or "Ngừng bán"))return "Thông tin món không hợp lệ.";var item=f??new Food{Id=state.Foods.Select(z=>z.Id).DefaultIfEmpty().Max()+1};item.Name=x[0];item.Category=x[1];item.Unit=x[2];item.Price=price;item.Active=x[4]=="Đang bán";if(f==null)state.Foods.Add(item);Log("Cập nhật món "+item.Name);return null;});}
 UserControl Inventory(){var v=new InventoryView();Items(v,state.Stocks);Click(v,"Receive",()=>{if(GridAt(v).SelectedItem is not Stock stock){Msg("Chọn nguyên liệu muốn nhập kho.");return;}SimpleForm("Nhập kho · "+stock.Name,new[]{("Số lượng nhập","1")},x=>{if(!decimal.TryParse(x[0],out decimal qty)||qty<=0)return "Số lượng phải lớn hơn 0.";stock.Quantity+=qty;Log("Nhập kho "+stock.Name);return null;});Navigate("inventory");});Click(v,"Add",()=>{SimpleForm("Thêm nguyên liệu",new[]{("Tên nguyên liệu",""),("Đơn vị","kg"),("Số lượng ban đầu","0"),("Tồn tối thiểu","0")},x=>{if(x[0]==""||x[1]==""||!decimal.TryParse(x[2],out var qty)||qty<0||!decimal.TryParse(x[3],out var min)||min<0)return "Dữ liệu không hợp lệ.";state.Stocks.Add(new(){Name=x[0],Unit=x[1],Quantity=qty,Min=min});Log("Thêm nguyên liệu "+x[0]);return null;});Navigate("inventory");});return v;}
 UserControl StaffPage(){var v=new StaffView();Items(v,state.Staff);Click(v,"Add",()=>{EditStaff(null);Navigate("staff");});Click(v,"Edit",()=>{if(GridAt(v).SelectedItem is Employee e){EditStaff(e);Navigate("staff");}else Msg("Chọn nhân viên.");});return v;}
 void EditStaff(Employee? old){if(!IsManager)return;var d=Own(new StaffDialog());Label(d,"Heading",old==null?"Thêm nhân viên và tài khoản":"Chỉnh sửa nhân viên và tài khoản");int seq=state.Staff.Count+1;while(state.Staff.Any(e=>e.Id==$"NV{seq:00}"||e.AccountCode==$"TK{seq:000}"))seq++;Set(d,"Code",old?.Id??$"NV{seq:00}");Set(d,"AccountCode",old?.AccountCode??$"TK{seq:000}");Set(d,"NameInput",old?.Name??"");Set(d,"Phone",old?.Phone??"");Set(d,"Email",old?.Email??"");Set(d,"Address",old?.Address??"");Set(d,"Username",old?.Username??"");At<DatePicker>(d,"Birthday").SelectedDate=old?.Birthday;SetChoice(d,"Gender",old?.Gender??"Nam");SetChoice(d,"Role",old?.Role??"Phục vụ");SetChoice(d,"Status",old?.Status??"Đang làm việc");SetChoice(d,"AccountStatus",old?.AccountStatus??"Hoạt động");At<TextBox>(d,"Code").IsReadOnly=old!=null;At<TextBox>(d,"AccountCode").IsReadOnly=old!=null;Click(d,"Cancel",d.Close);Click(d,"Save",()=>{string id=Text(d,"Code"),code=Text(d,"AccountCode"),name=Text(d,"NameInput"),phone=Text(d,"Phone"),email=Text(d,"Email"),username=Text(d,"Username"),pwd=Secret(d,"Password"),confirm=Secret(d,"Confirm");var birthday=At<DatePicker>(d,"Birthday").SelectedDate;if(!Regex.IsMatch(id,@"^NV[A-Za-z0-9_-]+$",RegexOptions.IgnoreCase)||!Regex.IsMatch(code,@"^TK[A-Za-z0-9_-]+$",RegexOptions.IgnoreCase)||name==""||!Regex.IsMatch(username,@"^[A-Za-z0-9_.-]{3,50}$")||!Regex.IsMatch(email,@"^[^\s@]+@[^\s@]+\.[^\s@]+$")||!Regex.IsMatch(phone,@"^[0-9+ ()-]{9,20}$")||birthday==null||birthday>DateTime.Today){MessageBox.Show(d,"Kiểm tra mã nhân viên, tài khoản, ngày sinh, tên, điện thoại, email và tên đăng nhập.");return;}if((old==null||pwd!=""||confirm!="")&&(pwd.Length<8||pwd!=confirm)){MessageBox.Show(d,"Mật khẩu tối thiểu 8 ký tự và phải trùng xác nhận.");return;}if(state.Staff.Any(x=>x!=old&&(x.Id.Equals(id,StringComparison.OrdinalIgnoreCase)||x.AccountCode.Equals(code,StringComparison.OrdinalIgnoreCase)||x.Username.Equals(username,StringComparison.OrdinalIgnoreCase)||x.Email.Equals(email,StringComparison.OrdinalIgnoreCase)))){MessageBox.Show(d,"Trùng mã, tên đăng nhập hoặc email.");return;}var emp=old??new Employee();emp.Id=id;emp.AccountCode=code;emp.Name=name;emp.Phone=phone;emp.Email=email;emp.Username=username;emp.Birthday=birthday;emp.Address=Text(d,"Address");emp.Gender=Choice(d,"Gender");emp.Role=Choice(d,"Role");emp.Status=Choice(d,"Status");emp.AccountStatus=Choice(d,"AccountStatus");if(old==null)state.Staff.Add(emp);Log("Cập nhật nhân viên "+id);d.Close();});d.ShowDialog();}
 UserControl Shifts(){var v=new ShiftsView();Items(v,state.Staff.Select((s,i)=>new {s.Name,s.Role,Shift=i%2==0?"Ca sáng":"Ca tối",Time=i%2==0?"08:00–14:00":"17:00–23:00"}).ToList());return v;}
 UserControl Promos(){var v=new PromosView();Items(v,new[]{new{Name="Giảm 10% hóa đơn",Percent="10%",Condition="Áp dụng khi chọn tại thanh toán",Status="Đang áp dụng"}});return v;}
 UserControl Reports(){var v=new ReportsView();void Refresh(){var range=Choice(v,"Range");DateTime start=range=="Ngày"?DateTime.Today:range=="Tuần"?DateTime.Today.AddDays(-(((int)DateTime.Today.DayOfWeek+6)%7)):new DateTime(DateTime.Today.Year,DateTime.Today.Month,1);var paid=state.Bills.Where(b=>b.PaidAt.HasValue&&b.PaidAt.Value>=start).ToList();var rev=paid.Sum(b=>b.Due);Label(v,"Revenue",Money(rev));Label(v,"Paid",paid.Count);Label(v,"Average",Money(paid.Count==0?0:rev/paid.Count));Label(v,"Busy",Count("Có Khách"));Items(v,paid.GroupBy(b=>b.PaidAt!.Value.Date).OrderBy(g=>g.Key).Select(g=>new {Day=g.Key.ToString("dd/MM/yyyy"),Revenue=Money(g.Sum(b=>b.Due)),Count=g.Count()}).ToList());}At<ComboBox>(v,"Range").SelectionChanged+=(_,_)=>Refresh();Refresh();return v;}
 UserControl Chat(){var v=new ChatView();var list=At<ListBox>(v,"Messages");void Refresh(){list.ItemsSource=null;list.ItemsSource=state.Messages.ToList();if(list.Items.Count>0)list.ScrollIntoView(list.Items[list.Items.Count-1]);}Refresh();Click(v,"Send",()=>{string msg=Text(v,"Message");if(msg=="")return;state.Messages.Add(role+": "+msg);Set(v,"Message","");Log("Gửi tin nhắn nội bộ demo");Refresh();});return v;}
 UserControl Logs(){var v=new LogsView();Items(v,state.Logs);return v;}
 UserControl Profile(){var v=new ProfileView();Set(v,"NameInput",user);Set(v,"Role",role);At<TextBox>(v,"Role").IsReadOnly=true;Click(v,"Save",()=>{if(Text(v,"NameInput")=="")return;user=Text(v,"NameInput");Navigate("profile");});Click(v,"Change",()=>{if(Secret(v,"Old")==""||Secret(v,"New").Length<8||Secret(v,"New")!=Secret(v,"Confirm")){Msg("Kiểm tra mật khẩu hiện tại, mật khẩu mới và xác nhận.");return;}Msg("Mô phỏng đổi mật khẩu; không lưu mật khẩu thật.");Navigate("profile");});return v;}
}
